head.script:
	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

    scwin.trigger1_onclick = function() {
        gridView1.setAllowChar("col1", "a-zA-Z");
    }

    scwin.trigger2_onclick = function() {
        gridView1.setAllowChar("col2", "0-9");
    }

    scwin.trigger3_onclick = function() {
        gridView1.setIgnoreChar("col1", "a-zA-Z");
    }

    scwin.trigger4_onclick = function() {
        gridView1.setIgnoreChar("col2", "0-9");
    }

    scwin.trigger5_onclick = function() {
        gridView1.setIgnoreChar("col2", "0-9");
    }

    scwin.trigger11_onclick = function() {
        input1.setAllowChar("a-zA-Z");
    }

    scwin.trigger22_onclick = function() {
        input1.setAllowChar("0-9");
    }

    scwin.trigger33_onclick = function() {
        input1.setIgnoreChar("a-zA-Z");
    }

    scwin.trigger44_onclick = function() {
        input1.setIgnoreChar("0-9");
    }

    scwin.trigger55_onclick = function() {
        input1.setIgnoreChar("0-9");
    }

	scwin.fireDbClick = function(node){
		if( document.createEventObject ) {
			node.fireEvent('ondblclick') ;
		} else if( document.createEvent ) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function' ) {
			node.ondblclick();
		}
	}

	scwin.Dbclick = function(id){
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick (el);
	}	

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#G_'+$p.id+'gridView1__col2', 'key-sequence', {
			sequence: '123'
		});
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_0_1').innerText != '123';
	}		
	scwin.unitTest = function(){
		//init
		WebSquare.wUnit.start();

		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4_center').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_1')");	
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");	
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_1_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
